#[no_mangle]
pub unsafe extern "C" fn nagel_schrekenberg(v:*const i64,n:usize,out:*mut u8,cap:usize)->i64{
 if v.is_null()||n<5{return -1}let cells=*v;let steps=*v.add(1);let max_speed=*v.add(2);if !(2..=32).contains(&cells)||!(0..=16).contains(&steps)||!(0..=5).contains(&max_speed)||n!=cells as usize+3{return -1}let cells=cells as usize;let steps=steps as usize;let mut row=[-1i64;32];for i in 0..cells{let x=*v.add(i+3);if !(-1..=5).contains(&x){return -1}row[i]=x}let need=cells*(steps+1);if need>cap||out.is_null(){return -2}let mut p=0;for j in 0..cells{*out.add(p)=(row[j]+1) as u8;p+=1}for _ in 0..steps{let mut next=[-1i64;32];for i in 0..cells{if row[i]!=-1{let mut d=0usize;let mut j=i+1;while j<cells&&row[j]==-1{d+=1;j+=1}if j==cells{j=0;while row[j]==-1{d+=1;j+=1}}let mut speed=(row[i]+1).min(max_speed);speed=speed.min(d as i64-1);next[i]=speed}}let mut moved=[-1i64;32];for i in 0..cells{if next[i]!=-1{moved[(i+next[i] as usize)%cells]=next[i]}}for j in 0..cells{row[j]=moved[j];*out.add(p)=(row[j]+1)as u8;p+=1}}p as i64
}
